window.VN_LEARNING['lesson-14']={
version:1,title:'Practical Applications of Vegetarianism',chapter:'Chapter 17 + contemporary food practice',duration:'75–90 minutes',
outcomes:['Shop for a vegetarian pattern in ordinary grocery settings while using cost and access strategies.','Compare labels for protein, fortification, sodium, added sugars, allergens and intended use.','Store and prepare grains, legumes, tofu and leftovers safely.','Choose egg and dairy substitutions according to the culinary job they must perform.','Build flexible meals and counsel respectfully across budgets, cultures and vegetarian patterns.'],
modules:[
{id:'shop',title:'Shop with a purpose, not a specialty-store myth',summary:'Use ordinary food environments, labels and a flexible list.',moments:[
{id:'l14-m1',title:'Vegetarian shopping starts in ordinary aisles',highYield:'Legumes, grains, vegetables, fruit, nuts, seeds and many fortified foods are widely available; a special vegetarian store is optional, not required.',teaching:['A practical list begins with foods the household already uses, then identifies protein foods, staples, produce, fortified products and flavour builders. Canned and frozen foods can be nutritious, affordable and time-saving. Specialty products add convenience but are not required for adequacy.','Farmers’ markets can offer fresh local produce, but price, season, organic status and accessibility vary. “Natural food store” also describes many business models; it is inaccurate to assume these stores mainly sell supplements or that every market product is organic.'],keyPoints:['Ordinary grocery stores can support the pattern.','Canned and frozen foods are useful.','Specialty products are optional.','Price and organic status vary by vendor.'],visual:{title:'Flexible shopping map',kind:'map',items:[{label:'Protein foods',detail:'Beans, lentils, tofu, tempeh, soy, nuts, seeds, eggs/dairy if used'},{label:'Staples',detail:'Grains, bread, pasta, potatoes and pantry basics'},{label:'Produce',detail:'Fresh, frozen, canned or dried options'},{label:'Fortified foods',detail:'Selected beverages, cereals, yeast or analogues with verified labels'},{label:'Flavour',detail:'Herbs, spices, sauces and acids'}]},mnemonic:{title:'P-S-P-F-F',cue:'Protein · Staples · Produce · Fortified · Flavour',explanation:'Five list categories that work in many stores.'},goodToKnow:'“Organic,” “natural,” “vegan” and “nutritious” are different claims. One label does not guarantee the others.',practiceConnection:'Ask where the person actually shops and what equipment, transport and money are available before suggesting niche products.',activity:{prompt:'Which statement about vegetarian shopping is most accurate?',options:[{text:'A balanced pattern can be built largely from foods in ordinary grocery stores',correct:true,feedback:'Correct. Specialty stores may help but are not required.'},{text:'Farmers’ market produce is always organic',correct:false,feedback:'Certification and farming practice vary.'},{text:'Vegetarian cooking requires meat analogues at every meal',correct:false,feedback:'Legumes, tofu, grains, nuts and seeds can supply the foundation.'}]}},
{id:'l14-m2',title:'A label tells you whether a product fits the intended job',highYield:'A plant product can be suitable ethically yet fail to replace the protein, fortification or culinary function of the food it replaces.',teaching:['For plant beverages, compare serving size, protein, energy, calcium, vitamin D, B12, iodine where listed, added sugars and allergens. For meat analogues, compare protein, sodium, saturated fat and the overall role in the meal. Fortification varies and products change.','Ingredient lists help identify allergens and animal-derived ingredients, while the nutrition panel answers different questions. “Vegan” does not mean low sodium, high protein or fortified. Decide first what job the product must perform.'],keyPoints:['Match serving sizes.','Check protein and fortification.','Use the ingredient list for composition/allergens.','Match the product to its job.'],visual:{title:'Label-to-job sequence',kind:'sequence',items:[{label:'Name the job',detail:'Drink, protein food, recipe liquid, snack or supplement vehicle'},{label:'Check macros',detail:'Energy, protein, fat and carbohydrate'},{label:'Check key nutrients',detail:'Fortification and sodium/sugar context'},{label:'Check ingredients',detail:'Allergens and dietary fit'},{label:'Compare use',detail:'Does the product actually replace the intended role?'}]},mnemonic:{title:'J-M-N-I-U',cue:'Job · Macros · Nutrients · Ingredients · Use',explanation:'A five-step product comparison.'},goodToKnow:'A low-protein almond beverage may work in a recipe but may not replace a protein-rich beverage in a child’s daily pattern.',practiceConnection:'Record the exact product and label rather than advising from a generic category such as “plant milk.”',activity:{prompt:'What should be checked first when choosing a substitute product?',options:[{text:'What nutritional or culinary job it must perform',correct:true,feedback:'Correct. The job determines which label features matter.'},{text:'Whether the package is green',correct:false,feedback:'Package colour is not nutrition evidence.'},{text:'Whether it costs the most',correct:false,feedback:'Price does not establish suitability.'}]}}
]},
{id:'prep',title:'Prepare and store plant staples safely',summary:'Use systems that save time without turning practical customs into universal rules.',moments:[
{id:'l14-m3',title:'Dry storage protects quality; time and conditions determine method',highYield:'Grains, beans, flours, nuts and nutritional yeast keep best when protected from moisture, heat, pests, light and oxygen as appropriate.',teaching:['Clean airtight containers can protect pantry foods and make inventory visible, but original packaging may also be suitable if it closes well and is pest-resistant. Whole grains, whole-grain flours, nuts and seeds contain oils that can become rancid; cool or refrigerated storage can extend quality.','Nutritional yeast should be stored sealed, cool and dry; refrigeration or freezing can extend quality, especially in heat or humidity. Storage claims should follow the manufacturer and actual conditions rather than one universal “freezer after a month” rule.'],keyPoints:['Keep dry foods dry and sealed.','Use first-in, first-out rotation.','Higher-fat staples spoil faster.','Follow product-specific storage guidance.'],visual:{title:'Storage threat map',kind:'comparison',items:[{label:'Moisture',detail:'Clumping, mould and quality loss'},{label:'Heat/light',detail:'Faster flavour and nutrient deterioration'},{label:'Oxygen',detail:'Rancidity in higher-fat foods'},{label:'Pests',detail:'Contamination and waste'},{label:'Time',detail:'Rotate and date opened products'}]},mnemonic:{title:'M-H-O-P-T',cue:'Moisture · Heat · Oxygen · Pests · Time',explanation:'Five storage threats to manage.'},goodToKnow:'Containers do not make food shelf-stable forever; smell, appearance, dates and storage history still matter.',practiceConnection:'A pantry reset can reduce waste: label, date, group and plan meals around what is already open.',activity:{prompt:'Which storage plan best protects whole-grain flour?',options:[{text:'Seal it well and use cool storage, refrigerating or freezing for longer keeping',correct:true,feedback:'Correct. Its natural oils can become rancid.'},{text:'Leave it open beside the stove',correct:false,feedback:'Heat, oxygen and moisture shorten quality.'},{text:'Add water before storing it',correct:false,feedback:'Moisture raises spoilage risk.'}]}},
{id:'l14-m4',title:'Beans become practical through planning, not rigid soaking rules',highYield:'Soaking can shorten cooking and improve tolerance for some people, but soaking time varies and some legumes need little or none.',teaching:['Sort and rinse dry legumes. Larger beans often benefit from several hours or overnight soaking; lentils and split peas commonly cook without soaking. Discarding soak water may reduce some fermentable compounds, while pressure cooking and gradual intake can improve tolerance.','Boil kidney beans vigorously according to food-safety guidance because undercooked red kidney beans can contain harmful lectin. Canned beans are already cooked; rinse if desired to reduce surface sodium. Gas is normal microbial fermentation, and tolerance often improves gradually.'],keyPoints:['Soaking time depends on legume size and method.','Lentils often need no soak.','Cook kidney beans safely.','Increase legumes gradually for tolerance.'],visual:{title:'Legume workflow',kind:'sequence',items:[{label:'Choose',detail:'Dry, canned, lentil, split pea or bean'},{label:'Sort + rinse',detail:'Remove debris and rinse'},{label:'Soak if useful',detail:'Method depends on size and schedule'},{label:'Cook fully',detail:'Use safe time and temperature'},{label:'Portion + store',detail:'Cool promptly and use or freeze'}]},mnemonic:{title:'C-S-S-C-S',cue:'Choose · Sort · Soak · Cook · Store',explanation:'A flexible legume routine.'},goodToKnow:'Avoiding soaking does not reliably prevent gas; soaking, rinsing, portion size and adaptation can all influence tolerance.',practiceConnection:'Batch-cook and freeze meal-sized portions, or use low-sodium canned beans when time and energy are limited.',activity:{prompt:'Which statement about legumes is accurate?',options:[{text:'Soaking needs vary, and lentils often cook without soaking',correct:true,feedback:'Correct. One fixed 4–8-hour rule does not fit every legume.'},{text:'Undercooked red kidney beans are always safe',correct:false,feedback:'They require proper cooking to reduce lectins.'},{text:'Never rinsing canned beans is required',correct:false,feedback:'Rinsing is optional and can reduce surface sodium.'}]}}
]},
{id:'substitute',title:'Substitute by culinary function',summary:'Replace binding, lift, moisture and richness deliberately.',moments:[
{id:'l14-m5',title:'An egg performs several different jobs',highYield:'A substitute works only when it matches the egg’s role: binding, moisture, leavening, emulsifying, structure or foam.',teaching:['Mashed banana can add moisture and some binding in sweet baked goods, but it adds flavour and cannot reproduce every egg function. Ground flax or chia gel can bind; blended silken tofu adds moisture and structure; commercial replacers vary.','Aquafaba—the cooking liquid from chickpeas or other legumes—is especially useful for foams and some meringues. It is not nutritionally or functionally identical to scrambled egg. Choose the substitute from the recipe’s mechanism, then test texture and flavour.'],keyPoints:['Identify the egg’s job.','Banana suits some sweet baked goods.','Flax/chia and tofu bind differently.','Aquafaba is useful for foams.'],visual:{title:'Egg-function matching',kind:'comparison',items:[{label:'Bind',detail:'Flax/chia gel, tofu or commercial replacer'},{label:'Moisten',detail:'Banana, applesauce or tofu depending on recipe'},{label:'Lift',detail:'Leavener plus acid or formulated replacer'},{label:'Foam',detail:'Aquafaba'},{label:'Egg dish',detail:'Seasoned tofu is a different food, not an identical substitute'}]},mnemonic:{title:'B-M-L-F',cue:'Bind · Moisture · Lift · Foam',explanation:'Name the job before choosing the substitute.'},goodToKnow:'About 60 mL of mashed banana can replace an egg in some recipes, but recipe size and desired texture determine success.',practiceConnection:'Teach one recipe experiment at a time and record the result; universal substitution charts often overpromise.',activity:{prompt:'Which substitute is especially suited to vegan meringue?',options:[{text:'Whipped aquafaba',correct:true,feedback:'Correct. Its proteins and starches can form a foam.'},{text:'Dry uncooked beans',correct:false,feedback:'The cooking liquid, not dry beans, is used.'},{text:'Two cups of plant milk for one egg',correct:false,feedback:'This does not match the foam or binding function.'}]}},
{id:'l14-m6',title:'Milk substitution is usually one-to-one in volume, not two-to-one',highYield:'In most recipes, one cup of cow’s milk is replaced with about one cup of a suitable plant beverage; doubling the liquid usually disrupts the recipe.',teaching:['Choose an unsweetened beverage when sweetness would be unwanted. Soy beverage often supplies more protein and performs well in savoury sauces and baking; oat may add body; coconut changes flavour and fat; acidic recipes can cause some products to separate.','Culinary interchangeability does not equal nutritional interchangeability. A beverage used in a cake contributes differently to the total diet than a daily beverage chosen for protein and fortification.'],keyPoints:['Start with equal volume.','Choose flavour and texture for the recipe.','Unsweetened is useful for savoury dishes.','Culinary and nutritional replacement are different.'],visual:{title:'Beverage substitution filter',kind:'sequence',items:[{label:'Volume',detail:'Usually start 1:1'},{label:'Sweetness',detail:'Unsweetened or flavoured'},{label:'Body',detail:'Thin, creamy or high-fat'},{label:'Protein',detail:'Matters in some sauces and the overall diet'},{label:'Fortification',detail:'Matters for habitual drinking, not recipe chemistry alone'}]},mnemonic:{title:'V-S-B-P-F',cue:'Volume · Sweetness · Body · Protein · Fortification',explanation:'Five checks for plant beverage use.'},goodToKnow:'Fortified nutrients do not necessarily remain evenly suspended; shake products as directed.',practiceConnection:'For a client replacing milk, clarify whether the goal is cooking, drinking, protein, calcium/vitamin D or allergy management.',activity:{prompt:'How should plant beverage usually replace milk in a recipe initially?',options:[{text:'Use approximately equal volume, then adjust for the specific recipe',correct:true,feedback:'Correct. Doubling liquid usually changes structure.'},{text:'Always use twice as much plant beverage',correct:false,feedback:'This is likely to make the recipe too wet.'},{text:'Choose only by package colour',correct:false,feedback:'Recipe function and flavour matter.'}]}}
]},
{id:'apply',title:'Build flexible meals and counsel respectfully',summary:'Turn pantry components into meals that fit culture, budget and skill.',moments:[
{id:'l14-m7',title:'A meal formula reduces decision fatigue',highYield:'A flexible formula creates variety without requiring a new recipe every day.',teaching:['Combine a grain or starch, protein food, vegetables or fruit, a flavour system and an energy-rich addition when useful. The same structure can become a lentil curry with rice, tofu noodle bowl, bean taco, hummus plate, pasta with white beans, or culturally familiar dish.','Batch components rather than identical finished meals: cook a grain and beans, wash produce, make a sauce and freeze portions. Use leftovers safely by cooling promptly, refrigerating, reheating thoroughly and following local time guidance.'],keyPoints:['Use a flexible meal formula.','Build from culturally familiar foods.','Batch components for variety.','Handle leftovers safely.'],visual:{title:'Five-part meal builder',kind:'layers',items:[{label:'Base',detail:'Grain, bread, potato, noodle or other starch'},{label:'Protein',detail:'Legume, tofu, tempeh, soy, seitan, egg/dairy if used'},{label:'Plants',detail:'Vegetables and/or fruit'},{label:'Flavour',detail:'Herbs, spices, sauce, acid and aromatics'},{label:'Energy/texture',detail:'Nuts, seeds, avocado or oil as needed'}]},mnemonic:{title:'B-P-P-F-E',cue:'Base · Protein · Plants · Flavour · Energy',explanation:'A meal formula rather than a rigid menu.'},goodToKnow:'Vegetarian cooking can be quick or slow, just like omnivorous cooking; canned foods, frozen vegetables and prepared tofu are legitimate time-saving tools.',practiceConnection:'Ask which dishes already fit the person’s culture and modify those before introducing unfamiliar specialty foods.',activity:{prompt:'Which dinner best follows the five-part meal builder?',options:[{text:'Rice, black beans, vegetables, salsa and avocado',correct:true,feedback:'Correct. It includes all five parts.'},{text:'Only lettuce with no other components',correct:false,feedback:'It lacks a protein and energy foundation.'},{text:'A supplement without food',correct:false,feedback:'Supplements do not replace a meal pattern.'}]}},
{id:'l14-m8',title:'Practical counselling uses experiments and backups',highYield:'Small tested changes are more sustainable than a perfect plan that depends on unlimited time, money and motivation.',teaching:['Choose one meal, shopping habit or preparation skill to practise. Define a backup for low-energy days: canned beans, frozen vegetables, whole-grain bread, fortified beverage, tofu, microwave grains or a suitable ready meal.','Review taste, cost, effort, GI tolerance, food safety and nutrient role. Vegetarian patterns range from lacto-ovo to vegan and culturally specific plant-forward approaches; avoid assuming one motive or level of restriction.'],keyPoints:['Start with one practical change.','Create low-effort backups.','Review cost, taste and tolerance.','Respect motives and pattern differences.'],visual:{title:'Practical change cycle',kind:'sequence',items:[{label:'Choose',detail:'One useful behaviour or meal'},{label:'Prepare',detail:'Ingredients, equipment and backup'},{label:'Try',detail:'Use it in real life'},{label:'Review',detail:'Taste, cost, effort, tolerance and nutrition'},{label:'Adapt',detail:'Keep, change or replace'}]},mnemonic:{title:'C-P-T-R-A',cue:'Choose · Prepare · Try · Review · Adapt',explanation:'Treat behaviour change as an experiment.'},goodToKnow:'White sugar processing varies by manufacturer and region. Vegan shoppers who avoid bone-char processing need brand-specific information rather than a universal claim.',practiceConnection:'Avoid moral rankings of food choices. Collaborative planning works better than testing whether a client is “vegetarian enough.”',activity:{prompt:'Which counselling plan is most sustainable?',options:[{text:'Test one meal change and create a realistic backup option',correct:true,feedback:'Correct. A small experiment produces usable information.'},{text:'Replace the entire pantry overnight regardless of budget',correct:false,feedback:'This can create waste and overwhelm.'},{text:'Assume every vegetarian has the same motivation',correct:false,feedback:'Motives and patterns differ.'}]}}
]}
],
caseStudy:{title:'A plan that depends on specialty products',scenario:'A new vegan client was given a costly seven-day menu using unfamiliar meat analogues, imported powders and daily scratch cooking. They shop at a standard grocery store, work shifts and stopped the plan after three days.',prompts:['Which assumptions made the plan fragile?','How could ordinary pantry foods and batch components replace specialty products?','Which labels need checking for B12, calcium, D and protein?','What two backup meals could fit shift work?'],takeaway:'Practical vegetarian nutrition begins with the person’s real stores, schedule, culture, skills and budget—not an idealized pantry.'},
recap:['Vegetarian shopping does not require a specialty store.','Product labels must be interpreted according to the job the food must perform.','Dry foods need protection from moisture, heat, oxygen, pests and time.','Legume soaking and cooking depend on the legume and method.','Egg substitutes must match binding, moisture, lift, structure or foam.','Plant beverages usually replace milk about one-to-one in recipe volume.','A five-part meal formula supports variety and flexibility.','Small experiments and backup meals make plans sustainable.'],
flashcards:[{front:'Shopping five',back:'Protein foods, staples, produce, fortified foods and flavour builders.',tag:'shopping'},{front:'Label-to-job',back:'Choose a product by the nutritional or culinary function it must perform.',tag:'label'},{front:'Fortification variability',back:'Added nutrients differ across brands, markets and reformulations; verify the label.',tag:'label'},{front:'Storage threats',back:'Moisture, heat/light, oxygen, pests and time.',tag:'storage'},{front:'First-in, first-out',back:'Use older safe stock before newer stock to reduce waste.',tag:'storage'},{front:'Legume workflow',back:'Choose, sort/rinse, soak if useful, cook fully and store safely.',tag:'beans'},{front:'Aquafaba',back:'Legume cooking liquid, commonly chickpea liquid, that can form foams such as meringue.',tag:'substitution'},{front:'Flax egg',back:'Ground flax plus water used mainly for binding, not every egg function.',tag:'substitution'},{front:'Plant beverage recipe ratio',back:'Usually begin around one-to-one by volume, then adjust.',tag:'substitution'},{front:'Culinary vs nutritional replacement',back:'A product may work in a recipe without replacing the original food’s protein or fortification.',tag:'label'},{front:'Meal builder',back:'Base, protein, plants, flavour and energy/texture.',tag:'meal'},{front:'Practical change cycle',back:'Choose, prepare, try, review and adapt.',tag:'practice'}],
practice:[{prompt:'List the five shopping categories.',answer:'Protein foods, staples, produce, fortified foods and flavour builders.',rationale:'The list is flexible across stores.',tag:'shopping'},{prompt:'Why identify a product’s job before reading the label?',answer:'The job determines whether protein, fortification, texture, sweetness or another feature matters most.',rationale:'Not all substitutes serve the same purpose.',tag:'label'},{prompt:'Name five storage threats.',answer:'Moisture, heat/light, oxygen, pests and time.',rationale:'Managing them protects quality and safety.',tag:'storage'},{prompt:'Do all legumes require 4–8 hours of soaking?',answer:'No. Needs vary; lentils and split peas often cook without soaking.',rationale:'One rule does not fit every legume.',tag:'beans'},{prompt:'Why must red kidney beans be cooked properly?',answer:'Undercooked beans can retain harmful lectins.',rationale:'This is a food-safety issue.',tag:'beans'},{prompt:'Match aquafaba to its main culinary strength.',answer:'Foam formation, including meringue-style applications.',rationale:'Substitutes work by function.',tag:'substitution'},{prompt:'What is the usual starting milk-substitution ratio?',answer:'About one-to-one by volume.',rationale:'Doubling liquid usually disrupts a recipe.',tag:'substitution'},{prompt:'Build a meal with BP PFE.',answer:'Choose a base, protein, plants, flavour and energy/texture component.',rationale:'The formula supports many cuisines.',tag:'meal'},{prompt:'Name two low-effort backups.',answer:'Examples include canned beans, tofu, frozen vegetables, microwave grains, fortified beverages or a suitable ready meal.',rationale:'Backups protect consistency on difficult days.',tag:'practice'},{prompt:'What makes counselling respectful?',answer:'Ask about motives, culture, budget and pattern; collaborate on realistic experiments without moral ranking.',rationale:'Vegetarian identities and constraints differ.',tag:'counselling'}]
};

// Evidence-strengthening extension: macrobiotic patterns and a practical assessment method.
window.VN_LEARNING['lesson-14'].version=2;
window.VN_LEARNING['lesson-14'].sources=[{title:'NCI PDQ · Nutrition in Cancer Care: macrobiotic diet evidence',url:'https://www.cancer.gov/about-cancer/treatment/side-effects/appetite-loss/nutrition-hp-pdq'},{title:'Review · The macrobiotic diet as treatment for cancer',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC6220645/'},{title:'Cohort study · Macrobiotic nutrition and child health',url:'https://pubmed.ncbi.nlm.nih.gov/8172122/'},{title:'NIH ODS · Iodine fact sheet for health professionals',url:'https://ods.od.nih.gov/factsheets/Iodine-HealthProfessional/'},{title:'Health Canada · Lectins in dry legumes',url:'https://www.canada.ca/en/health-canada/services/food-nutrition/food-safety/chemical-contaminants/natural-toxins/lectins-legumes.html'}];
window.VN_LEARNING['lesson-14'].duration='115–135 minutes';
window.VN_LEARNING['lesson-14'].outcomes.push('Describe macrobiotic diets as a variable philosophy-linked spectrum rather than a synonym for vegan eating.','Assess likely benefits, nutrient risks and unsupported disease-treatment claims in a macrobiotic pattern.','Use respectful harm-reduction counselling while protecting medical treatment and nutritional adequacy.');
window.VN_LEARNING['lesson-14'].modules.push({id:'macrobiotic',title:'Understand and assess macrobiotic practice',summary:'Separate the traditional pattern, its modern variations, plausible food-pattern benefits and clinically important risks.',moments:[
{id:'l14-m9',title:'Macrobiotic is a variable philosophy-linked pattern—not one fixed menu',highYield:'Ask what macrobiotic means to this person; the label can describe anything from a flexible whole-food pattern to a highly restrictive graded regimen.',teaching:['Modern macrobiotic practice developed from Japanese and Western interpretations of balance, seasonality and food philosophy. Common features include whole grains as a major staple, vegetables, legumes and soy foods, soups, fermented foods and sometimes sea vegetables. Some versions include small amounts of fish or other animal foods; stricter versions exclude them. It is therefore not automatically vegan, nutritionally complete or identical across teachers and households.','Traditional explanations may classify foods through concepts such as yin and yang. These ideas can be culturally or personally meaningful, but they are not established biochemical measures of nutrient adequacy or disease treatment. Nutrition assessment still requires recognizable evidence: energy and protein intake, food variety, reliable B12 and vitamin D, mineral sources, iodine exposure, growth or weight trajectory, symptoms and medical context.','The same visible bowl can have very different nutritional effects. Brown rice, vegetables and miso can be part of a balanced meal when joined by tofu or beans, an energy source and an appropriate nutrient plan. If the whole diet repeatedly consists of small amounts of grains, vegetables and tea while fats, protein foods, fortified foods and supplements are avoided, nutritional risk rises.'],keyPoints:['Define the actual version before assessing it.','Macrobiotic is not synonymous with vegan.','Philosophical balance does not establish nutrient adequacy.','Assess meals, portions, exclusions and frequency.'],visual:{title:'Macrobiotic spectrum',kind:'comparison',items:[{label:'Flexible',detail:'Whole grains and vegetables plus adequate legumes/soy, fats, fortified foods or supplements, and optional foods according to values'},{label:'Restrictive',detail:'Narrow permitted-food list, low fat, little concentrated protein, no fortification or supplementation'},{label:'Therapeutic claim',detail:'Pattern promoted as a cure or replacement for medical treatment—requires an evidence and safety response'},{label:'Assessment',detail:'Translate the label into actual intake, function, risk and follow-up'}]},mnemonic:{title:'V-E-R-S-I-O-N',cue:'Variety · Exclusions · Reliability · Supplements · Intake · Outcomes · Needs',explanation:'Define the version before judging the diet.'},goodToKnow:'Miso and other salty fermented foods can add flavour and cultural meaning, but they do not reliably provide vitamin B12 and their sodium contribution still matters.',practiceConnection:'Open with Tell me what macrobiotic eating looks like in your home rather than reciting a standard list that may not describe the client.',activity:{prompt:'Which description of macrobiotic diets is most accurate?',options:[{text:'They are variable patterns often centred on whole grains and vegetables, with the exact exclusions and animal foods differing',correct:true,feedback:'Correct. Assessment must define the actual version.'},{text:'Every macrobiotic diet is identical and strictly vegan',correct:false,feedback:'Versions differ and some include fish or other foods.'},{text:'The label alone proves nutrient adequacy',correct:false,feedback:'Adequacy depends on the foods, amounts, fortification and supplements actually used.'}]}},
{id:'l14-m10',title:'Potential benefits come from foods; restriction creates the main risks',highYield:'A macrobiotic pattern may contain health-supporting foods, but there is no evidence that it cures cancer and restrictive forms can cause malnutrition.',teaching:['Whole grains, legumes, soy foods, vegetables, nuts and seeds can provide fibre, unsaturated fat, micronutrients and phytochemicals. A pattern emphasizing these foods may share features with other health-supporting plant-rich patterns. This does not validate every macrobiotic rule or show that the pattern treats disease; benefits should be attributed to the foods and overall pattern supported by evidence.','More restrictive forms can be low in total energy, protein concentration, fat, vitamin B12, vitamin D, calcium, iodine and sometimes riboflavin. Iron and zinc bioavailability may also need attention. Historic cohort evidence in strictly macrobiotic infants documented growth and developmental harm alongside multiple deficiencies; it should not be generalized to every modern practitioner, but it demonstrates why growing children cannot safely rely on philosophy in place of nutritional safeguards.','Sea vegetables create a double problem: some provide little iodine and others, especially kelp, can provide excessive iodine. Their iodine content is too variable to use as a precise replacement for iodized salt or a measured supplement. Seaweed and fermented foods are also not dependable sources of active B12.','Cancer authorities report no clinical evidence that a macrobiotic diet cures cancer. Anyone using a restrictive pattern during cancer treatment may be especially vulnerable to weight and muscle loss when appetite, swallowing or absorption are already affected. The diet must not delay surgery, medicines, radiation or other evidence-based care.'],keyPoints:['Credit whole plant foods without endorsing unsupported rules.','Screen energy, protein, B12, D, calcium, iodine, iron and zinc.','Treat seaweed iodine as unpredictable.','Do not present macrobiotics as cancer treatment.'],visual:{title:'Evidence separation',kind:'layers',items:[{label:'Supported food features',detail:'Whole grains, legumes, vegetables, nuts and seeds can contribute to a healthful pattern'},{label:'Adequacy question',detail:'Does this version deliver enough energy, protein and critical micronutrients?'},{label:'Unproven claim',detail:'Yin–yang classification does not demonstrate clinical efficacy'},{label:'Unsafe substitution',detail:'Do not replace or delay evidence-based cancer or medical treatment'}]},mnemonic:{title:'F-A-C-T',cue:'Foods · Adequacy · Claims · Treatment',explanation:'Separate useful foods from adequacy, disease claims and medical treatment decisions.'},goodToKnow:'An older textbook may describe one standard macrobiotic percentage formula, but current practice is too variable for that formula to define every client.',practiceConnection:'If a client has cancer, unplanned weight loss or treatment side effects, coordinate promptly with the oncology dietitian and medical team while preserving acceptable foods wherever possible.',activity:{prompt:'What is the best evidence-based response to a claim that a macrobiotic diet cures cancer?',options:[{text:'Acknowledge the persons goals, explain that clinical evidence does not show a cure, protect medical treatment and assess nutrition risk',correct:true,feedback:'Correct. Respect and clear safety boundaries belong together.'},{text:'Encourage stopping oncology treatment immediately',correct:false,feedback:'The diet must not replace evidence-based cancer care.'},{text:'Assume every whole-grain food is dangerous',correct:false,feedback:'Many core foods can fit a sound diet; the concern is the total pattern and unsupported claim.'}]}},
{id:'l14-m11',title:'Use a respectful macrobiotic assessment and harm-reduction plan',highYield:'The practical goal is not to win an argument about identity; it is to keep meaningful foods while repairing concrete risks and protecting care.',teaching:['Begin with a nonjudgmental 24-hour or multi-day pattern and the clients own rules. Record portions, cooking methods, beverages, seaweed species and frequency, supplements, fortified foods, reasons for following the pattern and any therapeutic promises made by a teacher or influencer. Ask about weight change, energy, GI symptoms, menstrual or reproductive changes, bone health, neurologic symptoms and the medical plan.','Grade risk by both restriction and vulnerability. A flexible adult with stable intake and reliable B12 is different from an infant, pregnant person, frail older adult, person with an eating disorder, or patient losing weight during cancer therapy. Immediate concerns include growth faltering, developmental regression, neurologic symptoms, dehydration, rapid weight loss, swallowing difficulty and refusal of necessary medical care.','Use the smallest acceptable changes that close the largest gaps. Examples may include a dependable B12 supplement, verified vitamin D, an appropriate iodine strategy, more tofu or legumes, added nut or seed butter or oil for energy, a fortified beverage, algae-derived DHA when indicated, and a clear monitoring plan. If a person rejects a change, explore the underlying rule and offer more than one value-compatible option.'],keyPoints:['Ask what the pattern actually contains.','Assess both restriction and vulnerability.','Repair the highest-risk gaps first.','Coordinate when disease treatment or growth is involved.'],visual:{title:'Macrobiotic counselling pathway',kind:'sequence',items:[{label:'Listen',detail:'Meaning, rules, goals and trusted advisers'},{label:'Map',detail:'Foods, portions, supplements, seaweed and symptoms'},{label:'Stratify',detail:'Restriction × life stage × disease vulnerability'},{label:'Repair',detail:'Close the highest-risk gap with acceptable options'},{label:'Protect',detail:'Maintain medical care and set follow-up'}]},mnemonic:{title:'L-M-S-R-P',cue:'Listen · Map · Stratify · Repair · Protect',explanation:'A harm-reduction path that respects identity and safeguards health.'},goodToKnow:'A respectful approach is not passive. Clear statements about growth, deficiency or delaying medical treatment are compatible with cultural humility.',practiceConnection:'Document the exact safety agreement: which nutrient source will be used, which treatment continues, what symptoms trigger urgent care and when follow-up occurs.',activity:{prompt:'A client wants to remain macrobiotic but has no reliable B12 source. What is the best first repair?',options:[{text:'Offer a dependable measured B12 source that fits the clients values and verify the plan',correct:true,feedback:'Correct. This closes a high-consequence gap without requiring abandonment of the whole pattern.'},{text:'Recommend seaweed as a guaranteed B12 source',correct:false,feedback:'Seaweed is not a dependable active B12 source.'},{text:'Ignore the issue unless severe symptoms appear',correct:false,feedback:'Prevention is safer because neurologic harm can occur.'}]}}
]});
window.VN_LEARNING['lesson-14'].flashcards.push({front:'Macrobiotic spectrum',back:'A variable philosophy-linked pattern often centred on whole grains and vegetables; it is not automatically vegan or nutritionally complete.',tag:'macrobiotic'},{front:'VERSION assessment',back:'Variety, exclusions, reliability, supplements, intake, outcomes and needs.',tag:'macrobiotic'},{front:'FACT evidence check',back:'Separate foods, adequacy, claims and treatment.',tag:'macrobiotic'},{front:'Cancer claim boundary',back:'Clinical evidence does not show that a macrobiotic diet cures cancer or can replace oncology treatment.',tag:'macrobiotic'},{front:'Macrobiotic harm reduction',back:'Listen, map, stratify, repair and protect.',tag:'counselling'});
window.VN_LEARNING['lesson-14'].practice.push({prompt:'Why can the word macrobiotic not determine nutrient adequacy?',answer:'The pattern varies widely in exclusions, portions, animal foods, fortification and supplement use.',rationale:'Assess the actual version, not the label.',tag:'macrobiotic'},{prompt:'Name the main nutrition risks in a highly restrictive macrobiotic pattern.',answer:'Low energy, protein concentration, fat, B12, vitamin D, calcium and iodine, with possible concerns for riboflavin, iron and zinc.',rationale:'Risk increases with restriction and vulnerable life stages.',tag:'macrobiotic'},{prompt:'What is the evidence boundary for cancer?',answer:'There is no clinical evidence that macrobiotics cures cancer, and the diet must not replace or delay evidence-based treatment.',rationale:'Weight and muscle loss can make restrictive treatment-period diets especially harmful.',tag:'macrobiotic'},{prompt:'Use the LMSRP counselling pathway.',answer:'Listen to meaning and goals, map the actual diet, stratify risk, repair the highest-risk gap and protect medical care with follow-up.',rationale:'Respectful harm reduction is more useful than arguing over the label.',tag:'counselling'});
